//go:build dev

package ec2

import "github.com/overcast-sh/overcast/internal/capabilities"

func init() {
	capabilities.Default.Register(
		capabilities.Capability{Service: "ec2", Operation: "AcceptVpcPeeringConnection", Category: "General", Status: capabilities.StatusSupported, Notes: "Transitions from `pending-acceptance` to `active`"},
		capabilities.Capability{Service: "ec2", Operation: "AllocateAddress", Category: "General", Status: capabilities.StatusSupported, Notes: "Generates eipalloc- ID and synthetic public IP; Domain honoured; supports TagSpecification"},
		capabilities.Capability{Service: "ec2", Operation: "AssociateAddress", Category: "General", Status: capabilities.StatusSupported, Notes: "Associates EIP with instance; generates eipassoc- ID"},
		capabilities.Capability{Service: "ec2", Operation: "AssociateRouteTable", Category: "General", Status: capabilities.StatusSupported, Notes: "Associates route table with subnet"},
		capabilities.Capability{Service: "ec2", Operation: "AttachInternetGateway", Category: "General", Status: capabilities.StatusSupported, Notes: "Takes the VPC Docker network out of `--internal`, moving any containers already on it to the recreated network with their addresses and DNS aliases; fails with InternalError, attaching nothing, if Docker refuses. A network shared by several VPCs is external while any of them has a gateway"},
		capabilities.Capability{Service: "ec2", Operation: "AttachVpnGateway", Category: "General", Status: capabilities.StatusSupported, Notes: "Metadata-only VPC attachment"},
		capabilities.Capability{Service: "ec2", Operation: "AuthorizeSecurityGroupEgress", Category: "General", Status: capabilities.StatusSupported},
		capabilities.Capability{Service: "ec2", Operation: "AuthorizeSecurityGroupIngress", Category: "General", Status: capabilities.StatusSupported, Notes: "IpPermissions with protocol, ports, CIDR ranges"},
		capabilities.Capability{Service: "ec2", Operation: "CreateInternetGateway", Category: "General", Status: capabilities.StatusSupported, Notes: "Generates igw-xxx ID"},
		capabilities.Capability{Service: "ec2", Operation: "CreateKeyPair", Category: "General", Status: capabilities.StatusSupported, Notes: "Generates dummy fingerprint and key material"},
		capabilities.Capability{Service: "ec2", Operation: "CreateNatGateway", Category: "General", Status: capabilities.StatusSupported, Notes: "Requires subnet and EIP; supports TagSpecification"},
		capabilities.Capability{Service: "ec2", Operation: "CreateNetworkInterface", Category: "General", Status: capabilities.StatusSupported, Notes: "Requires subnet; assigns synthetic private IP"},
		capabilities.Capability{Service: "ec2", Operation: "CreateRoute", Category: "General", Status: capabilities.StatusSupported, Notes: "DestinationCidrBlock + GatewayId or NatGatewayId"},
		capabilities.Capability{Service: "ec2", Operation: "CreateRouteTable", Category: "General", Status: capabilities.StatusSupported, Notes: "VPC must exist; auto-creates local route"},
		capabilities.Capability{Service: "ec2", Operation: "CreateSecurityGroup", Category: "General", Status: capabilities.StatusSupported, Notes: "Default egress allow-all rule added on create"},
		capabilities.Capability{Service: "ec2", Operation: "CreateSubnet", Category: "General", Status: capabilities.StatusSupported, Notes: "VPC must exist; honors AvailabilityZone; defaults to region+\"a\""},
		capabilities.Capability{Service: "ec2", Operation: "CreateTags", Category: "General", Status: capabilities.StatusSupported, Notes: "Tag any resource by ID; visible to that resource's own describe"},
		capabilities.Capability{Service: "ec2", Operation: "CreateVpc", Category: "General", Status: capabilities.StatusSupported, Notes: "CidrBlock required; creates Docker bridge network (`--internal` unless IGW attached) and main route table"},
		capabilities.Capability{Service: "ec2", Operation: "CreateLaunchTemplate", Category: "General", Status: capabilities.StatusSupported, Notes: "Mints an lt- ID and version 1; LaunchTemplateData, VersionDescription and TagSpecification supported"},
		capabilities.Capability{Service: "ec2", Operation: "CreateLaunchTemplateVersion", Category: "General", Status: capabilities.StatusSupported, Notes: "Numbers from the latest version; SourceVersion inherits the parameters the request does not set"},
		capabilities.Capability{Service: "ec2", Operation: "CreateVpcEndpoint", Category: "General", Status: capabilities.StatusSupported, Notes: "Metadata-only; Gateway and Interface types accepted; state always \"available\""},
		capabilities.Capability{Service: "ec2", Operation: "CreateVpnGateway", Category: "General", Status: capabilities.StatusSupported, Notes: "Metadata-only; type ipsec.1 with AmazonSideAsn"},
		capabilities.Capability{Service: "ec2", Operation: "CreateVpcPeeringConnection", Category: "General", Status: capabilities.StatusSupported, Notes: "Both VPCs must exist; starts in `pending-acceptance` state"},
		capabilities.Capability{Service: "ec2", Operation: "DeleteInternetGateway", Category: "General", Status: capabilities.StatusSupported, Notes: "Must be detached first"},
		capabilities.Capability{Service: "ec2", Operation: "DeleteKeyPair", Category: "General", Status: capabilities.StatusSupported, Notes: "Idempotent (no error if not found)"},
		capabilities.Capability{Service: "ec2", Operation: "DeleteNatGateway", Category: "General", Status: capabilities.StatusSupported, Notes: "Marks as deleted"},
		capabilities.Capability{Service: "ec2", Operation: "DeleteNetworkInterface", Category: "General", Status: capabilities.StatusSupported},
		capabilities.Capability{Service: "ec2", Operation: "DeleteRoute", Category: "General", Status: capabilities.StatusSupported, Notes: "Removes route by RouteTableId + DestinationCidrBlock"},
		capabilities.Capability{Service: "ec2", Operation: "DeleteRouteTable", Category: "General", Status: capabilities.StatusSupported, Notes: "Cannot delete main route table"},
		capabilities.Capability{Service: "ec2", Operation: "DeleteSecurityGroup", Category: "General", Status: capabilities.StatusSupported, Notes: "Fails with DependencyViolation while attached to a running/pending instance; the VPC's default group answers CannotDelete"},
		capabilities.Capability{Service: "ec2", Operation: "DeleteSubnet", Category: "General", Status: capabilities.StatusSupported, Notes: "Fails with DependencyViolation while ENIs, non-terminated instances, or NAT gateways remain in the subnet"},
		capabilities.Capability{Service: "ec2", Operation: "DeleteTags", Category: "General", Status: capabilities.StatusSupported, Notes: "Remove tags by key; a resource's tags are removed with the resource"},
		capabilities.Capability{Service: "ec2", Operation: "DeleteVpc", Category: "General", Status: capabilities.StatusSupported, Notes: "Removes Docker network; fails with DependencyViolation while subnets, gateways, endpoints, peering connections, ENIs, or instances remain"},
		capabilities.Capability{Service: "ec2", Operation: "DeleteLaunchTemplate", Category: "General", Status: capabilities.StatusSupported, Notes: "Deletes the template and every version it owns"},
		capabilities.Capability{Service: "ec2", Operation: "DeleteLaunchTemplateVersions", Category: "General", Status: capabilities.StatusSupported, Notes: "Per-version outcomes; the default version is refused with OperationNotPermitted"},
		capabilities.Capability{Service: "ec2", Operation: "DeleteVpcEndpoints", Category: "General", Status: capabilities.StatusSupported, Notes: "Accepts VpcEndpointId.N; silently skips unknown IDs"},
		capabilities.Capability{Service: "ec2", Operation: "DeleteVpnGateway", Category: "General", Status: capabilities.StatusSupported, Notes: "Requires gateway to be detached"},
		capabilities.Capability{Service: "ec2", Operation: "DeleteVpcPeeringConnection", Category: "General", Status: capabilities.StatusSupported, Notes: "From `active` or `pending-acceptance`; transitions to `deleted`"},
		capabilities.Capability{Service: "ec2", Operation: "DescribeAccountAttributes", Category: "General", Status: capabilities.StatusSupported, Notes: "Hardcoded defaults (supported-platforms, max-instances…)"},
		capabilities.Capability{Service: "ec2", Operation: "DescribeAddresses", Category: "General", Status: capabilities.StatusSupported, Notes: "Selects by AllocationId.N; returns tags; Filters: allocation-id, association-id, domain, instance-id, network-interface-id, private-ip-address, public-ip"},
		capabilities.Capability{Service: "ec2", Operation: "DescribeAvailabilityZones", Category: "General", Status: capabilities.StatusSupported, Notes: "3 AZs per region (a, b, c); Filters: region-name, state, zone-name"},
		capabilities.Capability{Service: "ec2", Operation: "DescribeDhcpOptions", Category: "General", Status: capabilities.StatusSupported, Notes: "Returns a fabricated default DHCP options set; Filters: none"},
		capabilities.Capability{Service: "ec2", Operation: "DescribeImages", Category: "General", Status: capabilities.StatusSupported, Notes: "Hardcoded set of 4 AMIs (AL2, Ubuntu, Windows, AL2023); selects by ImageId.N; Filters: architecture, description, image-id, image-type, is-public, name, owner-id, root-device-type, state, virtualization-type"},
		capabilities.Capability{Service: "ec2", Operation: "DescribeInstanceTypes", Category: "General", Status: capabilities.StatusSupported, Notes: "Hardcoded set: t3.micro/small/medium, m5.large/xlarge; Filters: current-generation, instance-type, memory-info.size-in-mib, vcpu-info.default-vcpus"},
		capabilities.Capability{Service: "ec2", Operation: "DescribeInstances", Category: "General", Status: capabilities.StatusSupported, Notes: "Selects by InstanceId.N, raising InvalidInstanceID.NotFound for an ID the region does not hold and InvalidInstanceID.Malformed for one that is not an ID; Filters: availability-zone, image-id, instance-id, instance-state-code, instance-state-name, instance-type, placement.availability-zone, subnet-id, vpc-id, tag:<key>, tag-key, tag-value"},
		capabilities.Capability{Service: "ec2", Operation: "DescribeInternetGateways", Category: "General", Status: capabilities.StatusSupported, Notes: "Selects by InternetGatewayId.N, raising InvalidInternetGatewayID.NotFound for an ID the region does not hold and InvalidInternetGatewayId.Malformed for one that is not an ID; Filters: attachment.state, attachment.vpc-id, internet-gateway-id, tag:<key>, tag-key, tag-value"},
		capabilities.Capability{Service: "ec2", Operation: "DescribeKeyPairs", Category: "General", Status: capabilities.StatusSupported, Notes: "Selects by KeyName.N; Filters: fingerprint, key-name, key-pair-id"},
		capabilities.Capability{Service: "ec2", Operation: "DescribeNatGateways", Category: "General", Status: capabilities.StatusSupported, Notes: "Selects by NatGatewayId.N; Filters: nat-gateway-id, state, subnet-id, vpc-id, tag:<key>, tag-key, tag-value"},
		capabilities.Capability{Service: "ec2", Operation: "DescribeNetworkInterfaces", Category: "General", Status: capabilities.StatusSupported, Notes: "Selects by NetworkInterfaceId.N, raising InvalidNetworkInterfaceID.NotFound for an ID the region does not hold and InvalidNetworkInterfaceId.Malformed for one that is not an ID; Filters: availability-zone, description, mac-address, network-interface-id, status, subnet-id, vpc-id, tag:<key>, tag-key, tag-value"},
		capabilities.Capability{Service: "ec2", Operation: "DescribeRegions", Category: "General", Status: capabilities.StatusSupported, Notes: "Hardcoded list of 8 regions; Filters: endpoint, opt-in-status, region-name"},
		capabilities.Capability{Service: "ec2", Operation: "DescribeRouteTables", Category: "General", Status: capabilities.StatusSupported, Notes: "Selects by RouteTableId.N, raising InvalidRouteTableID.NotFound for an ID the region does not hold and InvalidRouteTableId.Malformed for one that is not an ID; includes NAT gateway routes; Filters: association.main, association.route-table-association-id, association.subnet-id, route-table-id, vpc-id, tag:<key>, tag-key, tag-value"},
		capabilities.Capability{Service: "ec2", Operation: "DescribeSecurityGroups", Category: "General", Status: capabilities.StatusSupported, Notes: "Selects by GroupId.N, raising InvalidGroup.NotFound for an ID the region does not hold and InvalidGroupId.Malformed for one that is not an ID; Filters: description, group-id, group-name, vpc-id, tag:<key>, tag-key, tag-value"},
		capabilities.Capability{Service: "ec2", Operation: "DescribeSubnets", Category: "General", Status: capabilities.StatusSupported, Notes: "Selects by SubnetId.N, raising InvalidSubnetID.NotFound for an ID the region does not hold and InvalidSubnetID.Malformed for one that is not an ID; includes tagSet for CDK subnet groups; Filters: availability-zone, cidr-block, state, subnet-id, vpc-id, tag:<key>, tag-key, tag-value"},
		capabilities.Capability{Service: "ec2", Operation: "DescribeTags", Category: "General", Status: capabilities.StatusSupported, Notes: "Filters: key, resource-id, resource-type, value"},
		capabilities.Capability{Service: "ec2", Operation: "DescribeVpcAttribute", Category: "General", Status: capabilities.StatusSupported, Notes: "Returns the stored enableDnsSupport or enableDnsHostnames value"},
		capabilities.Capability{Service: "ec2", Operation: "DescribeLaunchTemplateVersions", Category: "General", Status: capabilities.StatusSupported, Notes: "Resolves $Latest and $Default; honours LaunchTemplateVersion.N, MinVersion and MaxVersion; Filters: create-time, image-id, instance-type"},
		capabilities.Capability{Service: "ec2", Operation: "DescribeLaunchTemplates", Category: "General", Status: capabilities.StatusSupported, Notes: "Selects by LaunchTemplateId.N or LaunchTemplateName.N; Filters: create-time, launch-template-name, tag:<key>, tag-key, tag-value"},
		capabilities.Capability{Service: "ec2", Operation: "DescribeVpcEndpoints", Category: "General", Status: capabilities.StatusSupported, Notes: "Selects by VpcEndpointId.N; Filters: service-name, vpc-endpoint-id, vpc-endpoint-state, vpc-endpoint-type, vpc-id"},
		capabilities.Capability{Service: "ec2", Operation: "DescribeVpnGateways", Category: "General", Status: capabilities.StatusSupported, Notes: "Selects by VpnGatewayId.N; Filters: amazon-side-asn, attachment.state, attachment.vpc-id, availability-zone, state, type, vpn-gateway-id, tag:<key>, tag-key, tag-value"},
		capabilities.Capability{Service: "ec2", Operation: "DescribeVpcPeeringConnections", Category: "General", Status: capabilities.StatusSupported, Notes: "Selects by VpcPeeringConnectionId.N; Filters: accepter-vpc-info.vpc-id, requester-vpc-info.vpc-id, status-code, vpc-peering-connection-id"},
		capabilities.Capability{Service: "ec2", Operation: "DescribeVpcs", Category: "General", Status: capabilities.StatusSupported, Notes: "Selects by VpcId.N, raising InvalidVpcID.NotFound for an ID the region does not hold and InvalidVpcID.Malformed for one that is not an ID; Filters: cidr, isDefault, state, vpc-id, tag:<key>, tag-key, tag-value"},
		capabilities.Capability{Service: "ec2", Operation: "DetachInternetGateway", Category: "General", Status: capabilities.StatusSupported, Notes: "Puts the VPC Docker network back into `--internal`, moving attached containers the same way as AttachInternetGateway; fails with InternalError, detaching nothing, if Docker refuses. Stays external while another VPC sharing the network has a gateway"},
		capabilities.Capability{Service: "ec2", Operation: "DetachVpnGateway", Category: "General", Status: capabilities.StatusSupported, Notes: "Metadata-only VPC detachment"},
		capabilities.Capability{Service: "ec2", Operation: "DisassociateAddress", Category: "General", Status: capabilities.StatusSupported, Notes: "By AssociationId"},
		capabilities.Capability{Service: "ec2", Operation: "DisassociateRouteTable", Category: "General", Status: capabilities.StatusSupported, Notes: "Cannot disassociate main association"},
		capabilities.Capability{Service: "ec2", Operation: "ModifyLaunchTemplate", Category: "General", Status: capabilities.StatusSupported, Notes: "SetDefaultVersion only, accepting a version number or $Latest/$Default"},
		capabilities.Capability{Service: "ec2", Operation: "ModifyInstanceAttribute", Category: "General", Status: capabilities.StatusSupported, Notes: "InstanceType.Value persisted; all other attributes accepted"},
		capabilities.Capability{Service: "ec2", Operation: "ModifySubnetAttribute", Category: "General", Status: capabilities.StatusSupported, Notes: "MapPublicIpOnLaunch is persisted and returned by DescribeSubnets"},
		capabilities.Capability{Service: "ec2", Operation: "ModifyVpcAttribute", Category: "General", Status: capabilities.StatusSupported, Notes: "EnableDnsSupport, EnableDnsHostnames are persisted and returned by DescribeVpcAttribute"},
		capabilities.Capability{Service: "ec2", Operation: "ReleaseAddress", Category: "General", Status: capabilities.StatusSupported, Notes: "By AllocationId"},
		capabilities.Capability{Service: "ec2", Operation: "RevokeSecurityGroupEgress", Category: "General", Status: capabilities.StatusSupported},
		capabilities.Capability{Service: "ec2", Operation: "RevokeSecurityGroupIngress", Category: "General", Status: capabilities.StatusSupported},
		capabilities.Capability{Service: "ec2", Operation: "RunInstances", Category: "General", Status: capabilities.StatusSupported, Notes: "MinCount/MaxCount, TagSpecifications, async pending→running; each state emits an EC2 Instance State-change Notification to the default EventBridge bus. LaunchTemplate supplies ImageId, InstanceType, security groups, subnet and instance tags beneath any parameter the request passes"},
		capabilities.Capability{Service: "ec2", Operation: "StartInstances", Category: "General", Status: capabilities.StatusSupported, Notes: "From stopped state only; each state emits an EC2 Instance State-change Notification to the default EventBridge bus"},
		capabilities.Capability{Service: "ec2", Operation: "StopInstances", Category: "General", Status: capabilities.StatusSupported, Notes: "From running state only; async stopping→stopped; each state emits an EC2 Instance State-change Notification to the default EventBridge bus"},
		capabilities.Capability{Service: "ec2", Operation: "TerminateInstances", Category: "General", Status: capabilities.StatusSupported, Notes: "Async shutting-down→terminated transition; each state emits an EC2 Instance State-change Notification to the default EventBridge bus"},
		capabilities.Capability{Service: "ec2", Operation: "unbacked", Category: "VPC network states", Status: capabilities.StatusSupported, Notes: "No Docker network (Docker unavailable, or the last create failed)", DocOnly: true},
		capabilities.Capability{Service: "ec2", Operation: "conflict", Category: "VPC network states", Status: capabilities.StatusSupported, Notes: "Reserved for strict mode when CIDR collides with another existing VPC", DocOnly: true},
		capabilities.Capability{Service: "ec2", Operation: "remapped", Category: "VPC network states", Status: capabilities.StatusSupported, Notes: "Reserved for remapped mode and backed by a shadow CIDR", DocOnly: true},
	)
}
